(()=>{'use strict';const f=document.getElementById('prototype'),report=document.getElementById('report');document.getElementById('narrow').onclick=()=>f.style.width='320px';document.getElementById('phone').onclick=()=>f.style.width='390px';
const wait=async predicate=>{const end=performance.now()+12000;while(!predicate()){if(performance.now()>end)throw Error('Timed out waiting for ready state');await new Promise(r=>setTimeout(r,40));}};
document.getElementById('run').onclick=async()=>{let checks=[];const test=(name,ok,detail)=>{checks.push({name,status:ok?'PASS':'FAIL',...(detail?{detail}: {})});if(!ok)throw Error(name);};const click=el=>{if(!el)throw Error('Missing control');el.click();};const snap=()=>report.textContent=JSON.stringify({status:checks.every(x=>x.status==='PASS')?'PASS':'FAIL',environment:'Desktop Chrome, 390/320 CSS px; physical Safari and VoiceOver NOT TESTED',checks},null,2);
try{await wait(()=>f.contentDocument.querySelector('#existing-reader')?.contentDocument.querySelectorAll('.scripture-line').length===385);const d=f.contentDocument,r=d.querySelector('#existing-reader'),rd=r.contentDocument,rw=r.contentWindow;await rd.fonts.ready;await wait(()=>/^(Play|Resume) silent visual guide$/.test(rd.querySelector('#play').getAttribute('aria-label')));
const source=Array.from(rd.querySelectorAll('.tuk')).map(x=>x.textContent);const line=rd.querySelectorAll('.scripture-line')[60];rw.scrollTo({top:rw.scrollY+line.getBoundingClientRect().top-100,behavior:'instant'});test('Return anchor is tested well beyond the opening',rw.scrollY>500);let before=rw.scrollY;const node=rd.querySelector('.scripture-line');click(rd.querySelector('#play'));await wait(()=>rd.querySelector('#play').getAttribute('aria-pressed')==='true');
before=rw.scrollY;click(d.querySelector('#simran-open'));test('Entering a room pauses the existing silent guide',rd.querySelector('#play').getAttribute('aria-pressed')==='false');test('Underlying reader becomes inert while the modal is open',r.inert===true&&d.querySelector('#room').open);test('Simran offers five independent accessible views',d.querySelectorAll('[data-view]').length===5);
click(d.querySelector('[data-view="1"]'));test('Breath attention is opt-in and initially hidden',d.querySelector('#breath-cue').hidden);click(d.querySelector('#breath-choice'));test('Optional cue appears only after a deliberate action',!d.querySelector('#breath-cue').hidden&&d.querySelector('#breath-choice').getAttribute('aria-pressed')==='true');click(d.querySelector('#breath-choice'));test('Optional cue can be turned off immediately',d.querySelector('#breath-cue').hidden);
click(d.querySelector('[data-view="2"]'));test('Naam Simran withholds unreviewed practice instructions',d.querySelector('#simran-panel').textContent.includes('Practice instructions are withheld'));click(d.querySelector('[data-view="3"]'));test('Stillness requires no completion or timer',d.querySelector('#simran-panel').textContent.includes('Nothing to complete'));
click(d.querySelector('[data-view="4"]'));const originals=Array.from(d.querySelectorAll('[data-source-id]'));test('Both Learn passages exactly match the mounted original source',originals.length===2&&originals.every(e=>e.textContent===rd.querySelector('[data-occurrence="'+e.dataset.sourceId+'"] .tuk').textContent));test('Source and withheld interpretation remain distinct',d.querySelector('#simran-panel').textContent.includes('Interpretation and practical guidance'));
for(const width of [390,320]){f.style.width=width+'px';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));test(width+'px Simran has no horizontal overflow',d.querySelector('#room').scrollWidth<=d.querySelector('#room').clientWidth);test(width+'px Simran buttons meet 44px minimum',Array.from(d.querySelectorAll('#room button')).every(b=>{const rect=b.getBoundingClientRect();return rect.width>=44&&rect.height>=44;}));}f.style.width='390px';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));click(d.querySelector('#return-reader'));await wait(()=>!r.inert);test('Reader document and all 385 original texts survive return',r.contentDocument===rd&&rd.querySelector('.scripture-line')===node&&JSON.stringify(Array.from(rd.querySelectorAll('.tuk')).map(x=>x.textContent))===JSON.stringify(source));test('Return restores exact scroll offset without resuming',Math.abs(rw.scrollY-before)<=1&&rd.querySelector('#play').getAttribute('aria-pressed')==='false',{before,after:rw.scrollY});test('Return restores the opener and removes inert',d.activeElement.id==='simran-open'&&!r.inert);
click(d.querySelector('#arrival-open'));const select=d.querySelector('#place');for(const id of ['harmandir','fremont','sanjose']){select.value=id;select.dispatchEvent(new Event('change'));test(id+': local clock visible without a live-status claim',!!d.querySelector('#local-time').textContent&&d.querySelector('#place-detail').textContent.includes('does not indicate services'));test(id+': broadcaster is hidden before Enter or Skip',d.querySelector('#place-info').hidden);click(d.querySelector('#skip-arrival'));test(id+': Skip immediately reveals a deliberate outbound link',!d.querySelector('#place-info').hidden&&d.querySelector('.outbound').target==='_blank');}
test('There is no provider iframe, audio or video in either room',d.querySelectorAll('iframe').length===1&&d.querySelectorAll('audio,video').length===0);test('Fremont and San Jose uncleared Gurmukhi names are not invented',!d.querySelector('.place-gurmukhi'));
for(const width of [390,320]){f.style.width=width+'px';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));test(width+'px arrival has no horizontal overflow',d.querySelector('#room').scrollWidth<=d.querySelector('#room').clientWidth);const controls=Array.from(d.querySelectorAll('#room button,#room select,#room .outbound')).filter(x=>x.getClientRects().length);test(width+'px interactive targets meet 44px minimum',controls.every(x=>{const b=x.getBoundingClientRect();return b.width>=44&&b.height>=44;}));}
f.style.width='390px';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));click(d.querySelector('#return-reader'));await wait(()=>!r.inert);test('Arrival returns to the same existing reading document',r.contentDocument===rd&&Math.abs(rw.scrollY-before)<=1);snap();}catch(e){checks.push({name:'Harness completion',status:'FAIL',detail:e.message});snap();}};
})();
